def test_includes_conversation_threads(self, client_with_engine):
    """Test that state organizes messages into conversation threads."""
    client, engine = client_with_engine

    # User sends (from_number = user_phone_number +15559876543)
    client.post(
        "/sms/send",
        json={
            "from_number": "+15559876543",
            "to_numbers": ["+15551234567"],
            "body": "Hey there!",
        },
    )
    # User receives (from_number != user_phone_number)
    client.post(
        "/sms/receive",
        json={
            "from_number": "+15551234567",
            "to_numbers": ["+15559876543"],
            "body": "Hi! How are you?",
        },
    )

def test_includes_message_metadata(self, client_with_engine):
    """Test that state includes message metadata (read status, reactions, etc.)."""
    client, engine = client_with_engine

    # Receive a message (from someone else to user)
    client.post(
        "/sms/receive",
        json={
            "from_number": "+15551234567",
            "to_numbers": ["+15559876543"],
            "body": "Test message",
            "message_type": "rcs",
        },
    )

def test_pagination_with_offset(self, client_with_engine):
    """Test pagination using offset parameter."""
    client, engine = client_with_engine

    # User sends multiple messages
    for i in range(5):
        client.post(
            "/sms/send",
            json={
                "from_number": "+15559876543",
                "to_numbers": ["+15551234567"],
                "body": f"Message {i}",
            },
        )

    response = client.post("/sms/query", json={"limit": 2, "offset": 2})

    assert response.status_code == 200
    data = response.json()
    assert data["count"] == 2
    assert data["total_count"] == 5
    assert len(data["messages"]) == 2

def test_sort_by_timestamp(self, client_with_engine):
    """Test sorting messages by timestamp."""
    client, engine = client_with_engine

    # User sends messages (they'll have slightly different timestamps)
    client.post(
        "/sms/send",
        json={
            "from_number": "+15559876543",
            "to_numbers": ["+15551234567"],
            "body": "First message",
        },
    )
    client.post(
        "/sms/send",
        json={
            "from_number": "+15559876543",
            "to_numbers": ["+15551234567"],
            "body": "Second message",
        },
    )

